import {build} from 'esbuild';
import {writeFile} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';

export async function buildPowerPointRuntime() {
  const source=fileURLToPath(new URL('../src/powerpoint/runtime.js',import.meta.url));
  const result=await build({entryPoints:[source],bundle:true,platform:'browser',format:'iife',
    target:['chrome110','edge110','firefox115','safari16.4'],minify:true,legalComments:'inline',write:false});
  await writeFile(new URL('../src/vendor/powerPointRuntime.js',import.meta.url),
    '// Generated by scripts/build-powerpoint.mjs from src/powerpoint/runtime.js.\nexport default '+JSON.stringify(result.outputFiles[0].text)+';\n');
}
if(process.argv[1]===fileURLToPath(import.meta.url))await buildPowerPointRuntime();
